    private static function attachmentName(string $path):bool{return preg_match('~^(?:history/[a-f0-9-]{36}\.enc|exports/[a-f0-9-]{36}\.(?:json|csv))$~D',$path)===1;}
    private static function safeConfig(array $v):array {foreach($v as $key=>$value){if(preg_match('/(?:password|secret|encrypted|token_hash|salt|credential|private_key|master_key|api_key|write_key|authorization)/i',(string)$key))unset($v[$key]);elseif(is_array($value))$v[$key]=self::safeConfig($value);}return $v;}
    private static function exportValue(string $kind,array $value):array
    {
