        if($kind==='events'&&isset($value['payload']['props'])&&(is_array($value['payload']['props'])||is_object($value['payload']['props'])))$value['payload']['props']=(object)$value['payload']['props'];
        if($kind==='notification_jobs'&&isset($value['body']['invitation_url']))unset($value['body']['invitation_url']);return $value;
    }
    public static function exportSite(App $a,string $site,bool $full=true):array
