    public static function upgrade(App $a):array {$a->db->migrate();$privacy=Governance::replayJournal($a);return ['ok'=>true,'schema'=>$a->db->all('SELECT version FROM schema_migrations ORDER BY version'),'privacy_records_checked'=>count($privacy),'nodeLegacy'=>'Node scrypt/AES-GCM/PostgreSQL backups require the original runtime or an explicit audited converter'];}
