    public static function enqueueNotification(App $a,string $s,string $channel,array $body,string $dedupe):void {$id=hash('sha256',$s.':'.$dedupe);if($a->store->get('notification_jobs',$id))return;$a->store->put('notification_jobs',$id,['id'=>$id,'site_id'=>$s,'channel_id'=>$channel,'body'=>$body,'status'=>'pending','attempts'=>0,'next_at'=>Store::now(),'created_at'=>Store::now()],$s);}
