    }
    private static function alertFunnel(App $a,string $site,string $from,string $to,string $funnel):array
    {
        $stats=Analytics::stats($a,$site,['from'=>$from,'to'=>$to]);if(($stats['funnelStatus']??'')!=='supported')return [];$steps=((array)$stats['funnels'])[$funnel]??[];$rates=[];for($i=1;$i<count($steps);$i++)if($steps[$i-1]>0)$rates[$i]=$steps[$i]/$steps[$i-1];return $rates;
    }
    public static function register(App $a,Router $r):void
    {
        $r->add('GET','/api/admin/operations',function(Http $h)use($a){$a->auth->admin($h);return ['runtime'=>'PHP '.PHP_VERSION,'database'=>$a->db->one('SELECT VERSION() version')['version'],'schema'=>$a->db->all('SELECT version FROM schema_migrations'),'jobs'=>array_count_values(array_column($a->store->list('notification_jobs'),'status')),'journal_records'=>count(Governance::journal($a->config,true))];});
        $base='/api/v1/sites/:siteId';$r->add('GET',$base.'/storage/history',function(Http $h)use($a){$s=$h->params['siteId'];$a->auth->authorize($h,$s,'admin');return ['authority'=>'mysql','configured'=>true,'manifests'=>$a->store->list('history_manifests',$s)];});
        $r->add('POST',$base.'/storage/history/capture',function(Http $h)use($a){$s=$h->params['siteId'];$a->auth->authorize($h,$s,'admin');return $a->db->transaction(function()use($a,$s){$a->db->lock('site:'.$s);$data=self::exportSite($a,$s,true);$id=Store::uuid();$namespace=Store::uuid();$rows=[];foreach($data['tables'] as $kind=>$records)if(str_starts_with($kind,'stats_')||(str_starts_with($kind,'history_')&&!in_array($kind,['history_manifests','history_namespaces','history_backups'],true))||in_array($kind,['visitor_first_seen','goals','funnels'],true))$rows[$kind]=$records;$manifest=['id'=>$id,'site_id'=>$s,'namespace'=>$namespace,'status'=>'published','created_at'=>Store::now(),'tables'=>$rows,'site'=>array_intersect_key($a->store->get('sites',$s)??[],array_flip(['id','name','timezone','privacy_mode','retention_days','created_at','first_seen_history_complete'])),'references'=>array_column($a->store->list('history_manifests',$s),'id'),'sha256'=>hash('sha256',self::json($rows))];$a->store->put('history_manifests',$id,$manifest,$s);return ['manifest'=>$manifest];});});
        $r->add('POST',$base.'/storage/history/:id/backup',function(Http $h)use($a){$s=$h->params['siteId'];$a->auth->authorize($h,$s,'admin');$v=$a->store->get('history_manifests',$h->params['id']);if(!$v||$v['site_id']!==$s)Http::error(404,'history_missing');$path=$a->config['data_dir'].'/history/'.$v['id'].'.enc';$sealed=Security::seal(self::json($v),$a->config);self::writeFile($path,$sealed);Governance::write($a,$s,'history_backups',['id'=>$v['id'],'site_id'=>$s,'path'=>$path,'sha256'=>hash('sha256',$sealed),'created_at'=>Store::now()]);return ['id'=>$v['id'],'bytes'=>strlen($sealed),'integrity'=>$v['sha256'],'rows'=>array_sum(array_map('count',$v['tables']))];});
        $r->add('POST',$base.'/storage/history/:id/restore',function(Http $h)use($a){$s=$h->params['siteId'];$a->auth->authorize($h,$s,'admin');if(!preg_match('/^[a-f0-9-]{36}$/D',$h->params['id']))Http::error(400,'history_id_invalid');$ns=Governance::text($h->body['namespace']??null,64);if(!preg_match('/^[a-f0-9-]{36}$/D',$ns))Http::error(400,'history_namespace_invalid');return $a->db->transaction(function()use($a,$h,$s,$ns){$a->db->lock('site:'.$s);$path=$a->config['data_dir'].'/history/'.$h->params['id'].'.enc';if(!is_file($path))Http::error(404,'history_backup_missing');$v=json_decode(Security::unseal((string)file_get_contents($path),$a->config),true,512,JSON_THROW_ON_ERROR);if(($v['site_id']??null)!==$s||!hash_equals($v['sha256'],hash('sha256',self::json($v['tables']))))Http::error(409,'history_integrity_invalid');if($a->store->list('privacy_tombstones',$s))Http::error(409,'history_restore_requires_privacy_rebuild','存在删除边界；不能恢复缺少可逐人验证证据的历史聚合');$id=Store::uuid();$v['source_manifest']=$v['id'];$v['id']=$id;$v['namespace']=$ns;$v['created_at']=Store::now();$a->store->put('history_namespaces',$ns,$v,$s);return ['manifest'=>$v,'namespace'=>$ns,'activeStatisticsChanged'=>false];});});
    }
}
